@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--ink:#e7ebdf;--muted:#879286;--bg:#101611;--panel:#172019;--panel2:#1c281f;--line:#2c382e;--lime:#c7e77b;--green:#99be65;--mono:'DM Mono',monospace;--sans:'Space Grotesk',sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);min-height:100vh;background-image:radial-gradient(ellipse at 68% 32%,rgba(53,78,50,.14),transparent 40%),linear-gradient(90deg,rgba(255,255,255,.012) 1px,transparent 1px),linear-gradient(rgba(255,255,255,.012) 1px,transparent 1px);background-size:auto,36px 36px,36px 36px}.game-shell{max-width:1180px;margin:0 auto;padding:24px 40px 18px}.topbar{height:42px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #29342a;padding-bottom:17px}.brand{display:flex;gap:11px;align-items:center;text-decoration:none;color:#edf2e8;font-size:15px;font-weight:700;letter-spacing:.08em}.brand-amp{color:var(--lime);padding:0 2px}.brand-mark{width:24px;height:24px;display:grid;grid-template-columns:repeat(2,1fr);gap:2px;transform:rotate(-5deg)}.brand-mark i{display:block;background:var(--lime);border-radius:1px}.brand-mark i:nth-child(2){opacity:.7}.brand-mark i:nth-child(3){opacity:.5}.top-note,.sound-button,.eyebrow,.section-label,.level-pill,.overlay-kicker,.overlay-hint,.board-footer,.scene-caption,.materials-head,.material-note,.key-item small,.restart-button,.footer-note{font-family:var(--mono);letter-spacing:.08em}.top-note{font-size:9px;color:#899589;display:flex;gap:8px;align-items:center}.live-dot,.footer-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#a5d26c;box-shadow:0 0 9px #a5d26c}.sound-button{display:flex;align-items:center;gap:8px;color:#a6b0a3;border:1px solid #354136;background:#172019;padding:8px 11px;font-size:9px;border-radius:4px;cursor:pointer}.sound-button span:first-child{color:var(--lime);font-size:15px}.intro-row{display:flex;justify-content:space-between;align-items:flex-end;padding:29px 0 23px}.eyebrow{font-size:9px;color:#9da897;margin:0 0 12px}.eyebrow span{color:var(--lime)}h1{font-size:clamp(35px,4.2vw,52px);line-height:.98;letter-spacing:-.055em;margin:0;font-weight:600}h1 em{font-weight:500;color:var(--lime);font-style:normal}.intro-copy{max-width:278px;color:#a1ab9f;font-size:13px;line-height:1.55;margin:0 4px 3px 20px}.game-layout{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(350px,.92fr);gap:16px}.play-card,.home-card,.stats-card{background:rgba(23,32,25,.94);border:1px solid #303c31;border-radius:7px;overflow:hidden}.board-heading{height:62px;padding:12px 17px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #2b372d}.section-label{font-size:9px;color:#a2ad9e;display:block}.heading-sub{display:block;color:#69766a;font-size:10px;margin-top:3px}.level-pill{font-size:9px;color:#a0aa9c;border:1px solid #344035;padding:6px 9px;border-radius:3px}.level-pill b{color:#e0e9d8;font-weight:500}.level-spark{color:var(--lime);padding-right:4px}.board-stage{height:426px;position:relative;overflow:hidden;background:radial-gradient(ellipse at 52% 47%,rgba(74,101,64,.18),transparent 58%),linear-gradient(180deg,#19251c 0%,#151f18 100%);display:flex;align-items:center;justify-content:center}.board-backdrop{position:absolute;width:74%;height:100%;top:0;left:13%;opacity:.18;background-image:linear-gradient(90deg,rgba(173,197,156,.11) 1px,transparent 1px),linear-gradient(rgba(173,197,156,.11) 1px,transparent 1px);background-size:27px 27px;mask-image:linear-gradient(transparent,#000 20%,#000 85%,transparent)}#gameCanvas{display:block;position:relative;z-index:1;width:min(70%,305px);height:94%;filter:drop-shadow(0 11px 20px rgba(0,0,0,.32))}.board-overlay{position:absolute;inset:0;z-index:3;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;background:rgba(14,21,15,.78);backdrop-filter:blur(4px);transition:opacity .2s}.board-overlay.hidden{display:none}.overlay-icon{font-size:30px;line-height:1;color:var(--lime);margin-bottom:13px}.overlay-kicker{font-size:8px;color:#aab39f;margin:0 0 8px}.board-overlay h2{font-size:23px;line-height:1.15;letter-spacing:-.04em;margin:0 0 17px;font-weight:600}.primary-button{background:var(--lime);color:#182116;border:0;border-radius:3px;padding:12px 16px;font:700 10px var(--mono);letter-spacing:.04em;cursor:pointer;box-shadow:0 4px 18px #9abd4933;transition:transform .15s,background .15s}.primary-button:hover{background:#d8f39b;transform:translateY(-2px)}.primary-button span{font-size:14px;padding-left:13px}.overlay-hint{margin:12px 0 0;color:#7f8a7e;font-size:8px}.overlay-hint kbd{border:1px solid #475347;color:#bbc4b6}.board-footer{height:35px;display:flex;justify-content:space-between;align-items:center;padding:0 17px;border-top:1px solid #2b372d;color:#758174;font-size:8px}.board-footer b{color:#bbc6b8;font-weight:400}.board-footer>span:first-child{display:flex;gap:7px;align-items:center}.footer-dot{width:5px;height:5px}.side-column{display:grid;grid-template-rows:minmax(0,1fr) 81px;gap:12px;min-height:523px}.home-card{padding:15px 16px 12px;display:flex;flex-direction:column}.home-top{display:flex;align-items:flex-start;justify-content:space-between}.home-title{font-size:17px;font-weight:600;letter-spacing:-.04em;margin-top:4px}.edit-icon{font-size:12px;color:#819079;margin-left:4px}.weather{font-size:16px;color:#e8c878}.weather small{font:9px var(--mono);color:#9ba697}.scene-wrap{position:relative;flex:1;min-height:190px;margin:7px -3px 6px;border-radius:4px;overflow:hidden;background:linear-gradient(180deg,#273e36 0%,#526c50 55%,#536842 56%,#354e34 100%)}.scene-wrap:before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at 50% 48%,transparent 25%,rgba(7,15,12,.29) 100%),linear-gradient(0deg,rgba(15,27,16,.22),transparent 60%)}.scene-wrap:after{content:'';position:absolute;left:0;right:0;bottom:0;height:35%;opacity:.24;background-image:linear-gradient(30deg,transparent 48%,#97a96c 49%,#97a96c 51%,transparent 52%),linear-gradient(150deg,transparent 48%,#97a96c 49%,#97a96c 51%,transparent 52%);background-size:44px 26px}.scene-wrap canvas{position:absolute;inset:0;width:100%;height:100%;z-index:1}.scene-caption{position:absolute;z-index:2;bottom:9px;left:10px;font-size:7px;color:#d0d7bd;text-shadow:0 1px 5px #172318;letter-spacing:.08em}.scene-pin{color:var(--lime);font-size:7px;margin-right:4px}.build-progress{padding:3px 0 12px}.progress-copy{display:flex;justify-content:space-between;align-items:center;color:#a0ac9e;font-size:10px;margin-bottom:8px}.progress-copy b{font:11px var(--mono);color:var(--lime)}.progress-copy small{color:#748071;font-size:8px}.progress-track{height:4px;background:#303c30;border-radius:4px;position:relative;overflow:visible}.progress-track span{position:absolute;left:0;top:0;height:100%;width:0;background:var(--lime);border-radius:4px;transition:width .5s ease}.progress-track i{position:absolute;left:66.66%;top:-2px;height:8px;width:1px;background:#66755f}.materials{border-top:1px solid #303b31;padding-top:10px}.materials-head{display:flex;justify-content:space-between;align-items:center}.materials-head .section-label{font-size:8px}.material-note{font-size:7px;color:#657263}.material-list{display:flex;gap:7px;margin-top:9px}.material{height:29px;flex:1;min-width:0;background:#202c22;border:1px solid #303e30;border-radius:3px;display:flex;align-items:center;padding:0 6px;gap:6px}.material-cube{width:13px;height:13px;position:relative;flex:none;background:var(--mat);box-shadow:inset -3px -3px rgba(0,0,0,.22),inset 2px 2px rgba(255,255,255,.12)}.material-cube:after{content:'';position:absolute;inset:0;background:repeating-linear-gradient(0deg,transparent 0 4px,rgba(0,0,0,.12) 4px 5px)}.material-name{color:#a7b1a2;font-size:8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.material-count{font:9px var(--mono);color:#dbe5d2;margin-left:auto}.stats-card{display:flex;align-items:stretch;padding:0 4px}.stat{flex:1;padding:13px 12px;border-right:1px solid #303a31;display:flex;flex-direction:column;justify-content:center}.stat:last-child{border:0}.stat strong{font:19px var(--mono);letter-spacing:-.06em;color:#e5eddc;margin-top:6px}.stat:nth-child(2) strong{color:var(--lime)}.stat:nth-child(3){position:relative}.stat:nth-child(3) canvas{height:42px;width:58px;position:absolute;right:8px;bottom:4px}.bottom-row{display:flex;justify-content:space-between;align-items:center;padding:16px 2px 11px}.controls>.section-label{font-size:8px;margin-bottom:8px}.key-guide{display:flex;gap:12px}.key-item{display:flex;align-items:center;gap:3px}.key-item kbd,kbd{display:inline-flex;align-items:center;justify-content:center;min-width:19px;height:19px;padding:0 4px;background:#202b22;border:1px solid #3a473b;border-radius:3px;color:#bec8b9;font:9px var(--mono);box-shadow:0 2px 0 #0b100c}.key-item small{font-size:7px;color:#738071;margin-left:3px;white-space:nowrap}.restart-button{background:none;border:1px solid #354236;border-radius:3px;color:#aab5a5;padding:9px 11px;font-size:8px;cursor:pointer}.restart-button:hover{color:var(--lime);border-color:#718657}.restart-button span{font:15px var(--sans);vertical-align:-1px;margin-right:4px}.touch-controls{display:none}.footer-note{text-align:center;color:#647061;font-size:7px;padding-top:7px;letter-spacing:.14em}.footer-note span{color:#b4cf78;margin-left:5px}
@media(max-width:850px){.game-shell{padding:20px 24px}.game-layout{grid-template-columns:minmax(0,1fr) minmax(300px,.85fr);gap:12px}.board-stage{height:400px}.side-column{min-height:497px}.key-guide{gap:7px}.key-item small{font-size:6px}.intro-copy{max-width:235px}}
@media(max-width:700px){.game-shell{padding:15px 15px calc(18px + env(safe-area-inset-bottom))}.top-note{display:none}.intro-row{padding:24px 0 18px;align-items:flex-end}.intro-copy{font-size:11px;max-width:150px;margin:0 0 2px 12px}h1{font-size:39px}.game-layout{grid-template-columns:1fr}.side-column{grid-template-columns:minmax(0,1fr) 130px;grid-template-rows:1fr;min-height:310px;gap:10px}.home-card{padding:12px}.scene-wrap{min-height:145px}.home-title{font-size:15px}.stats-card{flex-direction:column;padding:4px}.stat{border-right:0;border-bottom:1px solid #303a31;padding:7px 8px;min-height:65px}.stat strong{font-size:17px;margin-top:4px}.stat:nth-child(3){min-height:74px}.stat:nth-child(3) canvas{width:64px;height:45px}.board-stage{height:min(105vw,420px);min-height:330px}.board-heading{height:56px}.bottom-row{padding-top:12px}.controls{display:none}.touch-controls{display:flex;gap:7px}.touch-controls button{border:1px solid #3b493c;background:#202b22;color:#e5eddc;border-radius:4px;width:38px;height:38px;font:18px var(--sans);touch-action:none}.touch-controls button[data-action=drop]{font:8px var(--mono);width:48px;color:var(--lime)}.restart-button{padding:9px 8px;font-size:7px}.footer-note{padding-bottom:2px}}
@media(max-width:390px){.game-shell{padding-left:10px;padding-right:10px}.intro-copy{max-width:128px;font-size:10px}.side-column{grid-template-columns:minmax(0,1fr) 110px}.material{padding:0 4px;gap:4px}.material-name{font-size:7px}}

(() => {
  const COLS = 10, ROWS = 20;
  const SHAPES = [
    { name: 'spruce', color: '#78a75b', light: '#a5cf78', dark: '#4c7144', map: [[1,1,1,1]] },
    { name: 'stone', color: '#84908b', light: '#b5c1b2', dark: '#57625e', map: [[1,0,0],[1,1,1]] },
    { name: 'oak', color: '#d49a54', light: '#f0c77a', dark: '#99613b', map: [[0,0,1],[1,1,1]] },
    { name: 'moss', color: '#d7c36e', light: '#f1df99', dark: '#a48c45', map: [[1,1],[1,1]] },
    { name: 'glass', color: '#5aa79a', light: '#a3ded0', dark: '#357569', map: [[0,1,1],[1,1,0]] },
    { name: 'brick', color: '#c77656', light: '#efaa7b', dark: '#914b3e', map: [[0,1,0],[1,1,1]] },
    { name: 'clay', color: '#8a7bc1', light: '#b9a9e8', dark: '#5d528b', map: [[1,1,0],[0,1,1]] }
  ];
  const $ = (id) => document.getElementById(id);
  const canvas = $('gameCanvas'), ctx = canvas.getContext('2d');
  const houseCanvas = $('houseCanvas'), houseCtx = houseCanvas.getContext('2d');
  const nextCanvas = $('nextCanvas'), nextCtx = nextCanvas.getContext('2d');
  let board, piece, nextPiece, score = 0, lines = 0, level = 1, running = false, started = false, gameOver = false;
  let dropTimer = 0, lastTime = 0, particles = [], audioOn = false, audioCtx = null;
  let best = Number(localStorage.getItem('blockBuildBest') || 0);
  $('bestScore').textContent = String(best).padStart(6, '0');

  function cloneShape(shape) { return { ...shape, map: shape.map.map(row => row.slice()) }; }
  function randomShape() { return cloneShape(SHAPES[Math.floor(Math.random() * SHAPES.length)]); }
  function newPiece(shape) { return { shape: shape || randomShape(), x: 3, y: -1 }; }
  function resetGame() {
    board = Array.from({ length: ROWS }, () => Array(COLS).fill(null));
    score = 0; lines = 0; level = 1; gameOver = false; started = true; running = true; dropTimer = 0;
    particles = []; piece = newPiece(randomShape()); nextPiece = randomShape();
    $('startOverlay').classList.add('hidden'); $('pauseOverlay').classList.add('hidden'); $('gameOverOverlay').classList.add('hidden');
    $('statusText').textContent = 'BUILDING IN PROGRESS'; updateHud(); requestAnimationFrame(loop);
  }
  function updateHud() {
    $('score').textContent = String(score).padStart(6, '0'); $('lines').textContent = String(lines).padStart(2, '0');
    $('level').textContent = String(level).padStart(2, '0');
    if (score > best) { best = score; localStorage.setItem('blockBuildBest', best); }
    $('bestScore').textContent = String(best).padStart(6, '0');
    const progress = Math.min(lines, 6);
    $('progressText').textContent = progress;
    $('progressBar').style.width = `${(progress / 6) * 100}%`;
    const phases = ['A place to begin', 'Laying the foundation', 'Walls are taking shape', 'Let the light in', 'A roof over your head', 'Adding the little details', 'Home sweet home'];
    $('buildPhase').textContent = phases[progress];
    renderMaterials(); drawNext(); drawHouse();
  }
  function renderMaterials() {
    const items = [
      ['Spruce', '#78a75b', Math.floor(lines * 4 + lines / 3)],
      ['Stone', '#84908b', Math.floor(lines * 3 + lines / 2)],
      ['Oak', '#d49a54', Math.floor(lines * 2 + lines / 4)],
      ['Glass', '#5aa79a', Math.max(0, lines - 2)]
    ];
    $('materials').innerHTML = items.map(([name, color, count]) => `<div class="material"><i class="material-cube" style="--mat:${color}"></i><span class="material-name">${name}</span><b class="material-count">${String(count).padStart(2, '0')}</b></div>`).join('');
  }
  function collides(p, dx = 0, dy = 0, map = p.shape.map) {
    for (let y = 0; y < map.length; y++) for (let x = 0; x < map[y].length; x++) if (map[y][x]) {
      const bx = p.x + x + dx, by = p.y + y + dy;
      if (bx < 0 || bx >= COLS || by >= ROWS || (by >= 0 && board[by][bx])) return true;
    }
    return false;
  }
  function rotateMap(map) { return map[0].map((_, i) => map.map(row => row[i]).reverse()); }
  function rotate() {
    if (!running) return;
    const rotated = rotateMap(piece.shape.map);
    for (const kick of [0, -1, 1, -2, 2]) if (!collides(piece, kick, 0, rotated)) { piece.shape.map = rotated; piece.x += kick; return; }
  }
  function move(dx, dy) {
    if (!running) return;
    if (!collides(piece, dx, dy)) { piece.x += dx; piece.y += dy; return true; }
    if (dy > 0) lockPiece();
    return false;
  }
  function lockPiece() {
    let above = false;
    piece.shape.map.forEach((row, y) => row.forEach((cell, x) => {
      if (!cell) return;
      const by = piece.y + y, bx = piece.x + x;
      if (by < 0) above = true;
      else board[by][bx] = piece.shape;
    }));
    if (above) { endGame(); return; }
    const cleared = [];
    for (let y = ROWS - 1; y >= 0; y--) if (board[y].every(Boolean)) { cleared.push(y); board.splice(y, 1); board.unshift(Array(COLS).fill(null)); y++; }
    if (cleared.length) {
      const points = [0, 100, 300, 500, 800][cleared.length] || 1000;
      score += points * level; lines += cleared.length; level = Math.floor(lines / 6) + 1;
      cleared.forEach(y => { for (let x = 0; x < COLS; x++) particles.push({ x, y, t: 0, color: piece.shape.light }); });
      playTone(680, .12); updateHud();
    } else score += 4;
    piece = newPiece(nextPiece); nextPiece = randomShape(); updateHud();
    if (collides(piece)) endGame();
  }
  function hardDrop() { if (!running) return; let distance = 0; while (!collides(piece, 0, 1)) { piece.y++; distance++; } score += distance * 2; lockPiece(); updateHud(); }
  function endGame() { running = false; gameOver = true; $('statusText').textContent = 'WORLD COMPLETE'; $('gameOverOverlay').classList.remove('hidden'); }
  function togglePause() {
    if (!started || gameOver) return;
    running = !running; $('pauseOverlay').classList.toggle('hidden', running); $('statusText').textContent = running ? 'BUILDING IN PROGRESS' : 'TAKE A BREATHER';
    if (running) { lastTime = performance.now(); requestAnimationFrame(loop); }
  }
  function loop(now) {
    if (!running) { drawGame(); return; }
    const dt = now - (lastTime || now); lastTime = now; dropTimer += dt;
    if (dropTimer > Math.max(90, 720 - (level - 1) * 55)) { move(0, 1); dropTimer = 0; }
    particles = particles.filter(p => p.t < 22); particles.forEach(p => p.t++);
    drawGame(); requestAnimationFrame(loop);
  }

  function resizeCanvas(c, context, draw, width, height) {
    const rect = c.getBoundingClientRect(); if (!rect.width || !rect.height) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2); c.width = Math.round(rect.width * dpr); c.height = Math.round(rect.height * dpr);
    context.setTransform(c.width / width, 0, 0, c.height / height, 0, 0); draw();
  }
  function drawCell(context, x, y, s, shape, alpha = 1) {
    context.save(); context.globalAlpha = alpha;
    const bevel = Math.max(2, s * .14);
    context.fillStyle = shape.color; context.fillRect(x + 1, y + 1, s - 2, s - 2);
    context.fillStyle = shape.light; context.beginPath(); context.moveTo(x + 1, y + 1); context.lineTo(x + s - 1, y + 1); context.lineTo(x + s - bevel, y + bevel); context.lineTo(x + bevel, y + bevel); context.closePath(); context.fill();
    context.fillStyle = shape.dark; context.beginPath(); context.moveTo(x + s - 1, y + 1); context.lineTo(x + s - 1, y + s - 1); context.lineTo(x + s - bevel, y + s - bevel); context.lineTo(x + s - bevel, y + bevel); context.closePath(); context.fill();
    context.fillStyle = 'rgba(255,255,255,.16)'; context.fillRect(x + bevel + 2, y + bevel + 2, Math.max(2, s * .12), Math.max(2, s * .12));
    context.strokeStyle = 'rgba(10,20,13,.4)'; context.lineWidth = 1; context.strokeRect(x + .5, y + .5, s - 1, s - 1); context.restore();
  }
  function drawGame() {
    const W = 300, H = 440; ctx.clearRect(0, 0, W, H);
    const cell = 22, ox = 40, oy = 0;
    ctx.fillStyle = 'rgba(7,13,9,.35)'; ctx.fillRect(ox - 3, oy, COLS * cell + 6, ROWS * cell + 2);
    ctx.fillStyle = '#142018'; ctx.fillRect(ox, oy, COLS * cell, ROWS * cell);
    for (let y = 0; y < ROWS; y++) for (let x = 0; x < COLS; x++) {
      ctx.fillStyle = (x + y) % 2 ? 'rgba(182,210,165,.035)' : 'rgba(182,210,165,.018)';
      ctx.fillRect(ox + x * cell, oy + y * cell, cell, cell);
      ctx.strokeStyle = 'rgba(173,197,156,.075)'; ctx.lineWidth = .6; ctx.strokeRect(ox + x * cell, oy + y * cell, cell, cell);
      if (board?.[y]?.[x]) drawCell(ctx, ox + x * cell, oy + y * cell, cell, board[y][x]);
    }
    if (piece && !gameOver) {
      let ghostY = piece.y; while (!collides({ ...piece, y: ghostY }, 0, 1)) ghostY++;
      piece.shape.map.forEach((row, y) => row.forEach((cellOn, x) => {
        if (!cellOn) return;
        const px = ox + (piece.x + x) * cell, py = oy + (ghostY + y) * cell;
        if (py >= 0) { ctx.strokeStyle = 'rgba(211,232,184,.38)'; ctx.lineWidth = 1; ctx.setLineDash([3,3]); ctx.strokeRect(px + 2, py + 2, cell - 4, cell - 4); ctx.setLineDash([]); }
      }));
      piece.shape.map.forEach((row, y) => row.forEach((cellOn, x) => { if (cellOn && piece.y + y >= 0) drawCell(ctx, ox + (piece.x + x) * cell, oy + (piece.y + y) * cell, cell, piece.shape); }));
    }
    particles.forEach(p => { ctx.globalAlpha = 1 - p.t / 22; ctx.fillStyle = p.color; ctx.fillRect(ox + p.x * cell + 4, oy + p.y * cell + 4 - p.t, cell - 8, cell - 8); }); ctx.globalAlpha = 1;
  }
  function drawNext() {
    nextCtx.clearRect(0, 0, 100, 66); if (!nextPiece) return;
    const m = nextPiece.map, s = 16, w = m[0].length * s, h = m.length * s, ox = (100 - w) / 2, oy = (66 - h) / 2;
    m.forEach((row,y)=>row.forEach((v,x)=>{if(v) drawCell(nextCtx,ox+x*s,oy+y*s,s,nextPiece);}));
  }

